import React from "react"
import { Link } from "gatsby"

const accentClasses = {
  cobalt: "from-[#1452ff] via-[#3284ff] to-[#7bdcff]",
  coral: "from-[#ff693d] via-[#ff8e3a] to-[#ffd25f]",
  lime: "from-[#b0ff46] via-[#71db57] to-[#1ba96b]",
  ink: "from-[#1b1c31] via-[#34417d] to-[#3bb5d9]",
}

function getInitials(title) {
  return title
    .split(" ")
    .slice(0, 2)
    .map((word) => word[0])
    .join("")
    .toUpperCase()
}

function GameCard({ game }) {
  const accentClass = accentClasses[game.accent] || accentClasses.cobalt

  return (
    <article className="arcade-panel p-4 sm:p-5">
      <div className={`relative overflow-hidden rounded-[24px] bg-gradient-to-br ${accentClass} p-5 text-white`}>
        <div className="absolute -right-5 top-4 h-16 w-16 rounded-full bg-white/20 blur-xl" />
        <div className="absolute bottom-0 left-6 h-12 w-24 rounded-full bg-[#cbff52]/30 blur-2xl" />
        <div className="relative flex min-h-[220px] flex-col justify-between">
          <div className="flex items-start justify-between gap-4">
            <span className="rounded-full border border-white/25 bg-white/10 px-3 py-1 text-[10px] font-bold uppercase tracking-[0.26em]">
              {game.genre}
            </span>
            <span className="rounded-full bg-[#1b1c31]/40 px-3 py-1 text-[10px] font-bold uppercase tracking-[0.24em]">
              {game.metric}
            </span>
          </div>
          <div className="space-y-3">
            <div className="display-heading text-5xl leading-none text-white/90">
              {getInitials(game.title)}
            </div>
            <p className="max-w-[16rem] text-sm font-medium leading-6 text-white/88">
              {game.stage}
            </p>
          </div>
        </div>
      </div>

      <div className="mt-5">
        <div className="flex items-start justify-between gap-4">
          <div>
            <h3 className="text-xl font-bold text-slate-900">{game.title}</h3>
            <p className="mt-2 text-sm leading-6 text-slate-600">{game.blurb}</p>
          </div>
          <span className="rounded-full bg-[#1b1c31] px-3 py-1 text-[10px] font-bold uppercase tracking-[0.22em] text-white">
            {game.status}
          </span>
        </div>

        <div className="mt-4 flex flex-wrap gap-2">
          {game.tags.map((tag) => (
            <span
              key={tag}
              className="rounded-full bg-[#f5eedf] px-3 py-1 text-xs font-medium text-slate-600"
            >
              {tag}
            </span>
          ))}
        </div>

        <div className="mt-5 flex items-center justify-between gap-4 border-t border-[rgba(27,28,49,0.1)] pt-4">
          <div>
            <p className="text-[11px] font-bold uppercase tracking-[0.24em] text-slate-500">
              Recommended slot
            </p>
            <p className="mt-1 text-sm font-medium text-slate-900">{game.slot}</p>
          </div>
          <Link
            to={`/games/${game.slug}`}
            className="rounded-full bg-slate-900 px-4 py-2 text-sm font-bold text-white transition-transform duration-200 hover:-translate-y-0.5"
          >
            Play now
          </Link>
        </div>
      </div>
    </article>
  )
}

export default GameCard
